partial class P {
 static async Task Security(){
  await Run("runtime-role-is-not-owner-or-bypass","security",async()=>{await using var c=await Db.Open();var safe=await Db.Scalar<bool>(c,"SELECT NOT rolsuper AND NOT rolbypassrls AND current_user<>(SELECT tableowner FROM pg_tables WHERE schemaname='poc' LIMIT 1) FROM pg_roles WHERE rolname=current_user");Check(safe,"unsafe runtime identity");return new{safe};});
  await Run("rls-tenant-company-and-missing-context","security",async()=>{
   foreach(var s in new[]{A,B,A2}){var count=await Db.Scoped(s,c=>Db.Scalar<long>(c,"SELECT count(*) FROM poc.scoped"));Check(count==1,"wrong scope count");}
   await using var c=await Db.Open();Check(await Db.Scalar<long>(c,"SELECT count(*) FROM poc.scoped")==0,"missing context leaks");
   var hidden=await Db.Scoped(A,x=>Db.Scalar<long>(x,"SELECT count(*) FROM poc.scoped WHERE tenant_id=@p0",B.Tenant));Check(hidden==0,"cross tenant visible");
   var company=await Db.Scoped(A,x=>Db.Scalar<long>(x,"SELECT count(*) FROM poc.scoped WHERE company_id=@p0",A2.Company));Check(company==0,"cross company visible");return new{scopes=3,missing=0,crossTenant=hidden,crossCompany=company};
  });
  await Run("rls-cross-scope-writes-and-resource-id","security",async()=>{
   await Expect(()=>Db.Scoped(A,c=>Db.Exec(c,"INSERT INTO poc.scoped VALUES(@p0,@p1,@p2,'attack')",Guid.NewGuid(),B.Tenant,B.Company)),"42501");
   await Expect(()=>Db.Scoped(A,c=>Db.Exec(c,"INSERT INTO poc.scoped VALUES(@p0,@p1,@p2,'attack')",Guid.NewGuid(),A.Tenant,A2.Company)),"42501");
   var victim=await Db.Scoped(B,c=>Db.Scalar<Guid>(c,"SELECT id FROM poc.scoped LIMIT 1"));
   Check(await Db.Scoped(A,c=>Db.Exec(c,"UPDATE poc.scoped SET label='attack' WHERE id=@p0",victim))==0,"modified ID write succeeded");return new{crossTenant="denied",crossCompany="denied",modifiedResource="zero rows"};
  });
  await Run("rls-pool-reuse-rollback-cancel-worker-support","security",async()=>{
   var cs=new NpgsqlConnectionStringBuilder(Db.Runtime){MaxPoolSize=1,ApplicationName="single-slot-rls"}.ToString();int pidA,pidB;
   await using(var c=await Db.Open(cs:cs)){pidA=c.ProcessID;await using var tx=await c.BeginTransactionAsync();await Db.SetScope(c,A);Check(await Db.Scalar<long>(c,"SELECT count(*) FROM poc.scoped WHERE tenant_id=@p0",A.Tenant)==1,"A missing");await tx.CommitAsync();}
   await using(var c=await Db.Open(cs:cs)){pidB=c.ProcessID;Check(pidA==pidB,"pool physical reuse not proven");Check(await Db.Scalar<long>(c,"SELECT count(*) FROM poc.scoped")==0,"context lingered");await using var tx=await c.BeginTransactionAsync();await Db.SetScope(c,B);Check(await Db.Scalar<long>(c,"SELECT count(*) FROM poc.scoped WHERE tenant_id=@p0",A.Tenant)==0,"A leaked into B");await tx.RollbackAsync();}
   await using(var c=await Db.Open(cs:cs)){await using var tx=await c.BeginTransactionAsync();await Db.SetScope(c,A);using var cancel=new CancellationTokenSource(100);try{await using var cmd=new NpgsqlCommand("SELECT pg_sleep(5)",c);await cmd.ExecuteNonQueryAsync(cancel.Token);throw new Exception("not cancelled");}catch(OperationCanceledException){}await tx.RollbackAsync();}
   await using(var c=await Db.Open(cs:cs)){Check(await Db.Scalar<long>(c,"SELECT count(*) FROM poc.scoped")==0,"cancel leaked");await using var tx=await c.BeginTransactionAsync();await Db.SetScope(c,B);Check(await Db.Scalar<long>(c,"SELECT count(*) FROM poc.scoped")==1,"worker wrong scope");await tx.CommitAsync();}
   // A support actor has only explicitly granted scope; there is no admin GUC bypass.
   var support=await Db.Scoped(A,c=>Db.Scalar<long>(c,"SELECT count(*) FROM poc.scoped WHERE tenant_id=@p0",B.Tenant));Check(support==0,"support bypass");
   return new{pidA,pidB,physicalReuse=true,afterRollback=0,afterCancellation=0,worker="scoped",support="no implicit bypass"};
  });
  await Run("malicious-context-parameter-fails-closed","security",async()=>{await Expect(async()=>{await using var c=await Db.Open();await using var tx=await c.BeginTransactionAsync();await Db.Exec(c,"SELECT set_config('app.tenant',@p0,true)","'; RESET ALL; --");await Db.Exec(c,"SELECT * FROM poc.scoped");},"22P02");return new{injectedSqlExecuted=false};});
  await Run("mass-assignment-field-and-upload-contract-rejections","security",()=>{
   var options=new System.Text.Json.JsonSerializerOptions{UnmappedMemberHandling=System.Text.Json.Serialization.JsonUnmappedMemberHandling.Disallow};
   bool denied=false;try{System.Text.Json.JsonSerializer.Deserialize<DraftInput>("{\"Amount\":100,\"TenantId\":\"B\",\"Posted\":true}",options);}catch(System.Text.Json.JsonException){denied=true;}Check(denied,"mass assignment accepted");
   var fields=new Dictionary<string,object>{{"id",1},{"amount",10m}};Check(!fields.ContainsKey("cost"),"cost leaked");
   bool ValidUpload(string mime,long length,string hash)=>mime=="application/pdf"&&length>0&&length<=1048576&&hash.Length==64&&hash.All(Uri.IsHexDigit);
   Check(!ValidUpload("text/html",100,"x"),"upload accepted");Check(!ValidUpload("application/pdf",2097152,new string('a',64)),"oversize accepted");return Task.FromResult<object?>(new{strictJson=true,restrictedDto=true,invalidUpload="denied",scope="contract function only; object-store scan pending"});
  });
 }
 record DraftInput(decimal Amount);
 static async Task Transactions(){
  await Run("posted-business-without-required-accounting-rejected","accounting",async()=>{await Expect(()=>Db.Scoped(A,c=>Db.Exec(c,"INSERT INTO poc.documents VALUES(@p0,@p1,@p2,'missing-ledger',10,'Posted')",Guid.NewGuid(),A.Tenant,A.Company)),"23514");Check(await Count("documents","missing-ledger")==0,"business operation committed without GL");return new{business=0,requiredAccountingMissing="commit rejected"};});
  await Run("ef-three-contexts-one-acid-commit","transactions",async()=>{var id=await Post("acid-ok","k",123.456789m);foreach(var t in new[]{"documents","journals","outbox"})Check(await Count(t,"acid-ok")==1,t+" missing");return new{id,documents=1,journals=1,outbox=1,contexts=3};});
  await Run("deferred-unbalanced-commit-rolls-back-everything","accounting",async()=>{await Expect(()=>Post("unbalanced","k",100m,broken:true),"23514");foreach(var t in new[]{"documents","journals","outbox"})Check(await Count(t,"unbalanced")==0,"partial "+t);return new{documents=0,journals=0,outbox=0};});
  await Run("ef-savechanges-unique-failure-outer-rollback","transactions",async()=>{await Expect(()=>Post("acid-ok","new-key",123.456789m),"23505");Check(await Count("documents","acid-ok")==1,"duplicate");var receipt=await Db.Scoped(A,c=>Db.Scalar<long>(c,"SELECT count(*) FROM poc.idempotency WHERE key='new-key'"));Check(receipt==0,"claim survived failure");return new{original=1,failedClaim=receipt};});
  await Run("explicit-rollback-after-savechanges","transactions",async()=>{var id=Guid.NewGuid();await using(var c=await Db.Open()){await using var tx=await c.BeginTransactionAsync();await Db.SetScope(c,A);await using var ctx=new BusinessDb(new DbContextOptionsBuilder<BusinessDb>().UseNpgsql(c).Options);await ctx.Database.UseTransactionAsync(tx);ctx.Add(new Document{id=id,tenant_id=A.Tenant,company_id=A.Company,source="rolled",amount=10});await ctx.SaveChangesAsync();await tx.RollbackAsync();}Check(await Count("documents","rolled")==0,"rollback did not rollback");return new{documents=0};});
  await Run("posting-closed-invalid-inactive-accounts","accounting",async()=>{foreach(var scenario in new[]{("closed",2,"Revenue"),("bad-account",1,"Missing"),("inactive",1,"Inactive")}){bool rejected=false;try{await Post(scenario.Item1,"k",10,period:scenario.Item2,credit:scenario.Item3);}catch(Exception e)when(e.Message.StartsWith("period.")||e.Message.StartsWith("account.")){rejected=true;}Check(rejected,"not rejected");Check(await Count("documents",scenario.Item1)==0,"partial business effect");}return new{rejections=3};});
  await Run("connection-interruption-rolls-back-and-fresh-uow-retries","transactions",async()=>{int pid;await using(var c=await Db.Open()){await using var tx=await c.BeginTransactionAsync();await Db.SetScope(c,A);pid=c.ProcessID;await Db.Exec(c,"INSERT INTO poc.documents VALUES(@p0,@p1,@p2,'disconnect',10,'Posted')",Guid.NewGuid(),A.Tenant,A.Company);await using var admin=await Db.Open(true);Check(await Db.Scalar<bool>(admin,"SELECT pg_terminate_backend(@p0)",pid),"terminate failed");try{await tx.CommitAsync();throw new Exception("commit should fail");}catch(Exception e)when(e is NpgsqlException||e is InvalidOperationException){}}
   Check(await Count("documents","disconnect")==0,"interruption committed");await Post("disconnect","retry",10);return new{terminatedPid=pid,initialEffects=0,retriedEffects=1};});
  await Run("postgres-deadlock-detected-and-full-uow-retry","transactions",async()=>{
   var ready1=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);var ready2=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);var errors=new List<string>();
   async Task Attempt(bool first){await using var c=await Db.Open();await using var tx=await c.BeginTransactionAsync();await Db.SetScope(c,A);var own=first?1:2;var other=first?2:1;await Db.Exec(c,"SELECT * FROM poc.periods WHERE id=@p0 FOR UPDATE",own);(first?ready1:ready2).SetResult();await(first?ready2:ready1).Task;try{await Db.Exec(c,"SELECT * FROM poc.periods WHERE id=@p0 FOR UPDATE",other);await tx.CommitAsync();}catch(PostgresException e)when(e.SqlState=="40P01"){lock(errors)errors.Add(e.SqlState);await tx.RollbackAsync();}}
   await Task.WhenAll(Attempt(true),Attempt(false));Check(errors.Count==1,"deadlock not injected");await Db.Scoped(A,async c=>{await Db.Exec(c,"SELECT * FROM poc.periods ORDER BY id FOR UPDATE");return 1;});return new{sqlstate=errors[0],victims=errors.Count,recovery="fresh transaction, consistent lock order"};
  });
  await Run("posted-history-update-delete-denied","security",async()=>{await Expect(()=>Db.Scoped(A,c=>Db.Exec(c,"UPDATE poc.lines SET debit=999")),"42501");await Expect(()=>Db.Scoped(A,c=>Db.Exec(c,"DELETE FROM poc.journals")),"42501");return new{immutable=true};});
 }
 static async Task Reservations(){
  foreach(var strategy in new[]{"atomic","row-lock","serializable","optimistic"})await Run("reservation-8-vs-7-"+strategy,"reservation",async()=>{
   int retries=0,deadlocks=0;var elapsed=new List<double>();var winners=new List<decimal>();
   for(int round=0;round<25;round++){var product=strategy+round;await NewPool(product);await Move(product,"opening",10,100);var start=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
    async Task<bool> Reserve(decimal q){await start.Task;var sw=Stopwatch.StartNew();for(int attempt=0;attempt<3;attempt++){await using var c=await Db.Open();await using var tx=await c.BeginTransactionAsync(strategy=="serializable"?IsolationLevel.Serializable:IsolationLevel.ReadCommitted);await Db.SetScope(c,A);try{int changed;
     if(strategy=="atomic")changed=await Db.Exec(c,"UPDATE poc.stock SET reserved=reserved+@p0,revision=revision+1 WHERE product=@p1 AND on_hand-reserved>=@p0",q,product);
     else {decimal available;long revision;await using(var cmd=Db.Cmd(c,"SELECT on_hand-reserved,revision FROM poc.stock WHERE product=@p0"+(strategy=="row-lock"?" FOR UPDATE":""),product)){await using var rd=await cmd.ExecuteReaderAsync();Check(await rd.ReadAsync(),"bucket missing");available=rd.GetDecimal(0);revision=rd.GetInt64(1);}if(available<q){await tx.RollbackAsync();return false;}await Task.Delay(3);changed=await Db.Exec(c,"UPDATE poc.stock SET reserved=reserved+@p0,revision=revision+1 WHERE product=@p1 AND on_hand-reserved>=@p0"+(strategy=="optimistic"?" AND revision=@p2":""),strategy=="optimistic"?[q,product,revision]:[q,product]);if(changed==0&&strategy=="optimistic"){await tx.RollbackAsync();Interlocked.Increment(ref retries);continue;}}
     if(changed==0){await tx.RollbackAsync();return false;}await Db.Exec(c,"INSERT INTO poc.reservations VALUES(@p0,@p1,@p2,@p3,@p4)",Guid.NewGuid(),A.Tenant,A.Company,product,q);await tx.CommitAsync();lock(elapsed)elapsed.Add(sw.Elapsed.TotalMilliseconds);return true;
    }catch(PostgresException e)when(e.SqlState is "40001" or "40P01"){if(e.SqlState=="40P01")Interlocked.Increment(ref deadlocks);Interlocked.Increment(ref retries);await tx.RollbackAsync();await Task.Delay(2+attempt*3);}}
    throw new Exception("bounded retry exhausted");}
    var one=Reserve(8);var two=Reserve(7);start.SetResult();var results=await Task.WhenAll(one,two);Check(results.Count(x=>x)==1,"two winners or no winner");var reserved=await Db.Scoped(A,c=>Db.Scalar<decimal>(c,"SELECT reserved FROM poc.stock WHERE product=@p0",product));var ledger=await Db.Scoped(A,c=>Db.Scalar<decimal>(c,"SELECT sum(quantity) FROM poc.reservations WHERE product=@p0",product));Check(reserved==ledger&&reserved<=10,"reservation reconciliation");await ReconcilePool(product);winners.Add(reserved);
   }
   return new{rounds=25,successfulReservations=25,doubleWinners=0,retries,deadlocks,minWinner=winners.Min(),maxWinner=winners.Max(),meanWinnerMs=elapsed.Average(),p95WinnerMs=elapsed.Order().ElementAt((int)(elapsed.Count*.95)),scope="single bucket adversarial pair, not production throughput benchmark"};
  });
  await Run("stale-concurrency-token-does-not-overwrite","reservation",async()=>{var changed=await Db.Scoped(A,c=>Db.Exec(c,"UPDATE poc.stock SET reserved=reserved+1,revision=revision+1 WHERE product='atomic0' AND revision=0"));Check(changed==0,"stale token accepted");return new{changed};});
 }
 static async Task Idempotency(){
  await Run("same-key-once-sequential-concurrent-timeout-replay","idempotency",async()=>{var id=await Post("idem","X",100);Check(await Post("idem","X",100)==id,"sequential mismatch");var many=await Task.WhenAll(Enumerable.Range(0,8).Select(_=>Post("idem","X",100)));Check(many.All(x=>x==id),"concurrent mismatch");var caller=Post("timeout","T",100);try{await caller.WaitAsync(TimeSpan.FromTicks(1));}catch(TimeoutException){}var committed=await caller;Check(await Post("timeout","T",100)==committed,"timeout replay duplicated");Check(await Count("documents","idem")==1&&await Count("journals","idem")==1&&await Count("outbox","idem")==1,"multiple effects");return new{sequential=2,concurrent=8,effects=1,clientTimeout=true,outboxDispatches="tested separately; no network inside posting"};});
  await Run("same-key-different-fingerprint-rejected","idempotency",async()=>{bool reject=false;try{await Post("idem","X",101);}catch(Exception e)when(e.Message=="idempotency.key_conflict"){reject=true;}Check(reject,"different payload accepted");Check(await Count("documents","idem")==1,"extra invoice");return new{conflict="idempotency.key_conflict",effects=1};});
  await Run("fresh-concurrent-key-and-business-source-uniqueness","accounting",async()=>{var values=await Task.WhenAll(Enumerable.Range(0,8).Select(_=>Post("fresh-idem","Y",50)));Check(values.Distinct().Count()==1,"multiple fresh effects");var ok=0;var failures=0;async Task PostDifferent(string key){try{await Post("source-once",key,25);Interlocked.Increment(ref ok);}catch(DbUpdateException e)when(e.InnerException is PostgresException p&&p.SqlState=="23505"){Interlocked.Increment(ref failures);}}await Task.WhenAll(PostDifferent("one"),PostDifferent("two"));Check(ok==1&&failures==1,"business uniqueness failed");return new{sameKeyConcurrent=8,effects=1,differentKeySuccess=ok,differentKeyConflict=failures};});
  await Run("process-killed-after-commit-replayed-once","idempotency",async()=>{var dll=Environment.GetCommandLineArgs()[0];var exe=Environment.ProcessPath!;var child=new Process{StartInfo=new ProcessStartInfo(exe){RedirectStandardOutput=true,RedirectStandardError=true}};child.StartInfo.ArgumentList.Add(dll);child.StartInfo.ArgumentList.Add("crash-post");child.Start();var output=await child.StandardOutput.ReadToEndAsync();await child.WaitForExitAsync();Check(child.ExitCode!=0&&output.Contains("COMMITTED_BEFORE_PROCESS_KILL"),"crash not proven");await Post("crash-source","crash-key",100);Check(await Count("documents","crash-source")==1,"crash retry duplicated");return new{exitCode=child.ExitCode,marker=output.Trim(),effects=1,recovery="query/replay existing receipt, no blind new command"};});
  await Run("replay-rechecks-current-authorization","security",async()=>{bool denied=false;try{await Post("idem","X",100,deny:true);}catch(UnauthorizedAccessException){denied=true;}Check(denied,"revoked actor replayed");return new{denied};});
 }
